USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementOfficer_GetAssigned @EmployeeId VARCHAR(30) AS BEGIN SET NOCOUNT ON; SELECT DISTINCT h.REQUISITION_ID,h.REQUISITION_NO,h.REQUESTED_DATE,h.TOTAL_ESTIMATED_AMOUNT,a.ASSIGNED_TO_EMPLOYEE_ID FROM dbo.REQUISITION_HEADER h JOIN dbo.REQUISITION_ITEM i ON i.REQUISITION_ID=h.REQUISITION_ID AND i.IS_ACTIVE=1 JOIN dbo.PROC_OFFICER_ASSET_MAP m ON m.ASSET_ID=i.ASSET_ID AND m.EMPLOYEE_ID=@EmployeeId AND m.IS_ACTIVE=1 AND m.EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME()) AND (m.EFFECTIVE_TO IS NULL OR m.EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME())) JOIN dbo.REQUISITION_ASSIGNMENT a ON a.REQUISITION_ID=h.REQUISITION_ID AND a.ASSIGNMENT_TYPE='PROCUREMENT_OFFICER_POOL' AND a.IS_CURRENT=1 WHERE h.CURRENT_STATUS='IN_WORKFLOW'; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementOfficer_TakeForReview @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000)=NULL
AS BEGIN SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRY BEGIN TRAN; IF NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_ASSIGNMENT WITH(UPDLOCK,HOLDLOCK) WHERE REQUISITION_ID=@RequisitionId AND ASSIGNMENT_TYPE='PROCUREMENT_OFFICER_POOL' AND IS_CURRENT=1 AND ASSIGNED_TO_EMPLOYEE_ID IS NULL) THROW 51003,'Request is not available for procurement review.',1; IF EXISTS(SELECT 1 FROM dbo.REQUISITION_ITEM i WHERE i.REQUISITION_ID=@RequisitionId AND i.IS_ACTIVE=1 AND NOT EXISTS(SELECT 1 FROM dbo.PROC_OFFICER_ASSET_MAP m WHERE m.ASSET_ID=i.ASSET_ID AND m.EMPLOYEE_ID=@ActorEmployeeId AND m.IS_ACTIVE=1 AND m.EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME()) AND (m.EFFECTIVE_TO IS NULL OR m.EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME())))) THROW 51002,'Officer is not mapped to all requisition assets.',1; UPDATE dbo.REQUISITION_ASSIGNMENT SET ASSIGNED_TO_EMPLOYEE_ID=@ActorEmployeeId WHERE REQUISITION_ID=@RequisitionId AND ASSIGNMENT_TYPE='PROCUREMENT_OFFICER_POOL' AND IS_CURRENT=1; INSERT dbo.APPROVAL_ACTION(REQUISITION_ID,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,ACTION_ROLE,FROM_STAGE,TO_STAGE,REMARKS) VALUES(@RequisitionId,'PROCUREMENT_OFFICER_TAKE',@ActorEmployeeId,'PROCUREMENT_OFFICER','PROCUREMENT_OFFICER','PROCUREMENT_OFFICER',@Remarks); COMMIT; SELECT '000' RESULT_CODE,N'Success' RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO; END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SELECT CASE ERROR_NUMBER() WHEN 51002 THEN '003' WHEN 51003 THEN '004' ELSE '999' END RESULT_CODE,ERROR_MESSAGE() RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO; END CATCH END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementOfficer_Approve @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000)=NULL,@BatchReferenceId UNIQUEIDENTIFIER=NULL
AS BEGIN SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRY BEGIN TRAN; IF NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_ASSIGNMENT WITH(UPDLOCK,HOLDLOCK) WHERE REQUISITION_ID=@RequisitionId AND ASSIGNMENT_TYPE='PROCUREMENT_OFFICER_POOL' AND IS_CURRENT=1 AND ASSIGNED_TO_EMPLOYEE_ID=@ActorEmployeeId) THROW 51002,'Actor does not own this review.',1; DECLARE @routes TABLE(RN INT,WORKFLOW_RULE_ID BIGINT,CONCERN_DIVISION_ID BIGINT,AUTHORITY_BEFORE_DIVISION BIT,DESTINATION_AFTER_CONCERN VARCHAR(30)); INSERT @routes SELECT ROW_NUMBER() OVER(PARTITION BY i.REQ_ITEM_ID ORDER BY r.PRIORITY_ORDER,CASE WHEN r.MIN_AMOUNT IS NULL THEN 1 ELSE 0 END,r.WORKFLOW_RULE_ID),r.WORKFLOW_RULE_ID,r.CONCERN_DIVISION_ID,r.AUTHORITY_BEFORE_DIVISION,r.DESTINATION_AFTER_CONCERN FROM dbo.REQUISITION_ITEM i JOIN dbo.WORKFLOW_RULE r ON r.ASSET_ID=i.ASSET_ID AND r.REQ_TYPE=i.REQ_TYPE AND r.IS_ACTIVE=1 AND r.EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME()) AND (r.EFFECTIVE_TO IS NULL OR r.EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME())) AND (r.MIN_AMOUNT IS NULL OR i.ESTIMATED_TOTAL_PRICE>=r.MIN_AMOUNT) AND (r.MAX_AMOUNT IS NULL OR i.ESTIMATED_TOTAL_PRICE<=r.MAX_AMOUNT) WHERE i.REQUISITION_ID=@RequisitionId AND i.IS_ACTIVE=1; IF (SELECT COUNT(*) FROM @routes WHERE RN=1)<>(SELECT COUNT(*) FROM dbo.REQUISITION_ITEM WHERE REQUISITION_ID=@RequisitionId AND IS_ACTIVE=1) THROW 51000,'A requisition item has no matching workflow rule.',1; IF (SELECT COUNT(DISTINCT CONCAT(COALESCE(CONCERN_DIVISION_ID,0),'|',AUTHORITY_BEFORE_DIVISION,'|',DESTINATION_AFTER_CONCERN)) FROM @routes WHERE RN=1)>1 THROW 51000,'Items resolve to incompatible workflow routes.',1; DECLARE @rule BIGINT,@div BIGINT,@before BIT,@dest VARCHAR(30),@next VARCHAR(40); SELECT TOP(1) @rule=WORKFLOW_RULE_ID,@div=CONCERN_DIVISION_ID,@before=AUTHORITY_BEFORE_DIVISION,@dest=DESTINATION_AFTER_CONCERN FROM @routes WHERE RN=1; SET @next=CASE WHEN @before=1 THEN 'PROCUREMENT_AUTHORITY' WHEN @div IS NOT NULL THEN 'CONCERN_DIVISION' ELSE @dest END; UPDATE dbo.REQUISITION_ASSIGNMENT SET IS_CURRENT=0,RELEASED_DATE=SYSUTCDATETIME() WHERE REQUISITION_ID=@RequisitionId AND IS_CURRENT=1; INSERT dbo.WORKFLOW_INSTANCE(REQUISITION_ID,WORKFLOW_RULE_ID,CURRENT_STAGE,CURRENT_OWNER_TYPE,CURRENT_OWNER_ORG_UNIT_ID,CURRENT_STATUS) SELECT @RequisitionId,@rule,@next,CASE WHEN @next='CONCERN_DIVISION' THEN 'ORG_UNIT' WHEN @next='READY_FOR_PROCUREMENT' THEN 'NONE' ELSE 'ROLE_POOL' END,CASE WHEN @next='CONCERN_DIVISION' THEN s.ORG_UNIT_ID END,CASE WHEN @next='READY_FOR_PROCUREMENT' THEN 'COMPLETED' ELSE 'PENDING' END FROM (SELECT 1 x) q LEFT JOIN dbo.CONCERN_DIVISION_SETUP s ON s.CONCERN_DIVISION_ID=@div; COMMIT; EXEC dbo.usp_Workflow_Advance @RequisitionId,@ActorEmployeeId,@next,'PROCUREMENT_OFFICER_APPROVE','PROCUREMENT_OFFICER',@next,@Remarks,@BatchReferenceId; END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SELECT CASE ERROR_NUMBER() WHEN 51000 THEN '001' WHEN 51002 THEN '003' ELSE '999' END RESULT_CODE,ERROR_MESSAGE() RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO; END CATCH END;
GO
